        private static List<PlanPoint> P(params double[] coordinates) {
            var points = new List<PlanPoint>(coordinates.Length / 2);
            for (int index = 0; index + 1 < coordinates.Length; index += 2) points.Add(new PlanPoint(coordinates[index], coordinates[index + 1]));
            return points;
        }

        private static SlopedPrismPiece S(List<PlanPoint> plan, double centreX, double centreZ, double topY0, double slopeX, double slopeZ, bool isFan) {
            return new SlopedPrismPiece(plan, centreX, centreZ, topY0, slopeX, slopeZ, isFan);
        }

        private static List<SlopedPrismPiece> Slopes(params SlopedPrismPiece[] slopes) {
            return new List<SlopedPrismPiece>(slopes);
        }

        private static List<(List<PlanPoint> Plan, double Top)> Plinths(params (List<PlanPoint> Plan, double Top)[] plinths) {
            return new List<(List<PlanPoint> Plan, double Top)>(plinths);
        }

    }
